    /// </summary>
    [JSInvokable]
    public async Task OnJsSketchCreate(IJSStreamReference jsStreamRef)
    {
        if (IsDisposed)
        {
            // cancel if the component is disposed
            return;
        }
    
        EditorViewModelSketchCreateEvent? sketchCreateEvent = await jsStreamRef.ReadJsStreamReference<EditorViewModelSketchCreateEvent>();
        if (sketchCreateEvent is not null)
        {
            await OnSketchCreate.InvokeAsync(sketchCreateEvent);
        }
    }
    
