    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case AttachmentsViewModel attachmentsViewModel:
                if (attachmentsViewModel != AttachmentsViewModel)
                {
                    AttachmentsViewModel = attachmentsViewModel;
                    ModifiedParameters[nameof(AttachmentsViewModel)] = AttachmentsViewModel;
                }
                
                return true;
            case FeatureTemplatesViewModel featureTemplatesViewModel:
                if (featureTemplatesViewModel != FeatureTemplatesViewModel)
                {
                    FeatureTemplatesViewModel = featureTemplatesViewModel;
                    ModifiedParameters[nameof(FeatureTemplatesViewModel)] = FeatureTemplatesViewModel;
                }
                
                return true;
            case EditorLayerInfo layerInfos:
                LayerInfos ??= [];
                if (!LayerInfos.Contains(layerInfos))
                {
                    LayerInfos = [..LayerInfos, layerInfos];
                    ModifiedParameters[nameof(LayerInfos)] = LayerInfos;
                }
                
                return true;
            case SnappingOptions snappingOptions:
                if (snappingOptions != SnappingOptions)
                {
                    SnappingOptions = snappingOptions;
                    ModifiedParameters[nameof(SnappingOptions)] = SnappingOptions;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case AttachmentsViewModel _:
                AttachmentsViewModel = null;
                ModifiedParameters[nameof(AttachmentsViewModel)] = AttachmentsViewModel;
                return true;
            case FeatureTemplatesViewModel _:
                FeatureTemplatesViewModel = null;
                ModifiedParameters[nameof(FeatureTemplatesViewModel)] = FeatureTemplatesViewModel;
                return true;
            case EditorLayerInfo layerInfos:
                LayerInfos = LayerInfos?.Where(l => l != layerInfos).ToList();
                ModifiedParameters[nameof(LayerInfos)] = LayerInfos;
                return true;
            case SnappingOptions _:
                SnappingOptions = null;
                ModifiedParameters[nameof(SnappingOptions)] = SnappingOptions;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        AttachmentsViewModel?.ValidateRequiredGeneratedChildren();
        FeatureTemplatesViewModel?.ValidateRequiredGeneratedChildren();
        if (LayerInfos is not null)
        {
            foreach (EditorLayerInfo child in LayerInfos)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        SnappingOptions?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
}
